interface.definition:
a!localVariables(

  #"SYSTEM_SYSRULES_formLayout_v2"(
    contents: {
      #"_a-0000ef67-4afa-8000-9e56-011c48011c48_1241120"(teamid: ri!teamid,selectedids: ri!selectedids,select: true())
    },
    buttons: #"SYSTEM_SYSRULES_ButtonLayout"(
      primaryButtons: {
        #"SYSTEM_SYSRULES_buttonWidget_v1"(
          label: "Submit",
          submit: true,
          saveInto:{ 
            a!save(
              target:ri!button,
              value:#"_a-0000eeda-0177-8000-9e52-011c48011c48_1085463"
            ),

          },
          loadingIndicator: true,
          style: "SOLID"
        )

      },
      secondaryButtons: {
        #"SYSTEM_SYSRULES_buttonWidget_v1"(
          label: "Cancel",
          value: true,
          saveInto: {
            a!save(
              target:ri!button,
              value:#"_a-0000eeda-0177-8000-9e52-011c48011c48_1085469"
            )
          },
          validate: false,
          submit: true,
          style: "OUTLINE"
        )
      }
    ),
    titleBar: #"SYSTEM_SYSRULES_headerTemplateFull"(
      title: "Select the application",
      secondaryText: "Enter your details",
      backgroundColor: "ACCENT"
    ),
    showTitleBarDivider: false
  )
)
